/*
 * A080682  19-smooth numbers: numbers whose prime divisors are all <= 19.
 * https://oeis.org/A080682
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 139, u16 n <= 2836, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Formula: a(n) = the n‑th smallest integer whose prime divisors are
 * all ≤ 19  (i.e., the n‑th 19‑smooth number)
 *
 * The sequence is generated by the classic "humble numbers" algorithm
 * with the prime set {2,3,5,7,11,13,17,19}.  A static cache is kept
 * so repeated calls work in O(1) time after the first cache build.
 */

#include <stddef.h>
#include <stdlib.h>
#include <string.h>

seq_t a(idx_t n)
{
    if (n < 1) return 0;  /* offset is 1; caller should not ask for n<1 */

    /* static cache */
    static seq_t *seq = NULL;          /* array of generated smooth numbers */
    static size_t seq_len = 0;         /* number of terms currently stored */
    static size_t seq_cap = 0;         /* current allocation capacity (≥ seq_len+1) */

    /* indices for each prime factor (1‑based indices into seq) */
    static size_t idx[8];
    static const uint64_t primes[8] = { 2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL, 17ULL, 19ULL };
    static int initialized = 0;

    /* initialise on first call */
    if (!initialized) {
        seq_cap = 16;
        seq = (seq_t *)malloc(seq_cap * sizeof(seq_t));
        if (!seq) return 0;           /* out of memory; caller will treat as 0 */
        seq[1] = (seq_t)1;            /* a(1) = 1 */
        seq_len = 1;
        for (int i = 0; i < 8; ++i) idx[i] = 1;
        initialized = 1;
    }

    /* grow cache if necessary */
    if (seq_len < (size_t)n) {
        if (n + 1 > seq_cap) {
            size_t new_cap = seq_cap > 0 ? seq_cap * 2 : 16;
            while (new_cap < (size_t)n + 1) new_cap *= 2;
            seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
            if (!tmp) return 0;        /* allocation failed */
            seq = tmp;
            seq_cap = new_cap;
        }

        /* generate terms up to n */
        while (seq_len < (size_t)n) {
            /* find the next candidate */
            seq_t next = seq[idx[0]] * (seq_t)primes[0];
            for (int p = 1; p < 8; ++p) {
                seq_t cand = seq[idx[p]] * (seq_t)primes[p];
                if (cand < next) next = cand;
            }

            /* store it */
            seq[++seq_len] = next;

            /* advance any indices that produced this value */
            for (int p = 0; p < 8; ++p) {
                if (seq[idx[p]] * (seq_t)primes[p] == next) idx[p] = idx[p] + 1;
            }
        }
    }

    return seq[n];
}
